package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"            // PIC X len=1 = "N"
var WsBal decimal.Decimal             // PIC 9(8)V99 len=10 = 0
var WsYear int64                     // PIC 99 len=2 = 0
var WsCount int64                    // PIC 99 len=2 = 0
var WsBalEd string                   // PIC ZZ,ZZZ,ZZ9.99 len=13
var curRec SchedRec
var schedLines []string
var schedIdx int

func pow10Int(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func storeInt(val int64, intDigits int) int64 {
	mod := pow10Int(intDigits)
	return val % mod
}

func storeDecimal(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	vtrunc := val.Truncate(int32(scale))
	total := intDigits + scale
	modPow := pow10Int(total)
	scaled := vtrunc.Shift(int32(scale)).Truncate(0).IntPart()
	scaled = scaled % modPow
	return decimal.New(scaled, int32(-scale))
}

func roundHalfAway(d decimal.Decimal, scale int) decimal.Decimal {
	factor := decimal.New(1, int32(scale))
	scaled := d.Mul(factor)
	trunc := scaled.Truncate(0)
	remainder := scaled.Sub(trunc)
	half := decimal.New(5, -1) // 0.5
	if scaled.Sign() >= 0 {
		if remainder.Cmp(half) >= 0 {
			trunc = trunc.Add(decimal.NewFromInt(1))
		}
	} else {
		negHalf := half.Neg()
		if remainder.Cmp(negHalf) <= 0 {
			trunc = trunc.Sub(decimal.NewFromInt(1))
		}
	}
	return trunc.Shift(-int32(scale))
}

func formatPIC99(v int64) string {
	truncated := storeInt(v, 2)
	return fmt.Sprintf("%02d", truncated)
}

func formatWsBalEd(val decimal.Decimal) string {
	scaled := val.Shift(2).Truncate(0).IntPart()
	isNeg := scaled < 0
	if isNeg {
		scaled = -scaled
	}
	intPart := scaled / 100
	fracPart := scaled % 100
	intStr := fmt.Sprintf("%08d", intPart)
	fracStr := fmt.Sprintf("%02d", fracPart)
	intPattern := "ZZ,ZZZ,ZZ9"
	intRunes := []rune(intPattern)
	mapped := make([]rune, len(intRunes))
	copy(mapped, intRunes)
	dIdx := 0
	for i, pc := range intRunes {
		if pc == 'Z' || pc == '9' {
			mapped[i] = rune(intStr[dIdx])
			dIdx++
		}
	}
	suppressed := true
	for i, pc := range intRunes {
		ch := mapped[i]
		if pc == 'Z' {
			if suppressed {
				if ch == '0' {
					mapped[i] = ' '
				} else {
					suppressed = false
				}
			}
		} else if pc == '9' {
			suppressed = false
		} else if pc == ',' {
			if suppressed {
				mapped[i] = ' '
			}
		}
	}
	intFormatted := string(mapped)
	return intFormatted + "." + fracStr
}

func parseImpliedDecimal(s string, scale int) decimal.Decimal {
	var b strings.Builder
	for _, r := range s {
		if r >= '0' && r <= '9' {
			b.WriteRune(r)
		}
	}
	digits := b.String()
	if digits == "" {
		return decimal.New(0, 0)
	}
	d, err := decimal.NewFromString(digits)
	if err != nil {
		return decimal.New(0, 0)
	}
	return d.Shift(int32(-scale))
}

func parseIntField(s string) int64 {
	var b strings.Builder
	for _, r := range s {
		if r >= '0' && r <= '9' {
			b.WriteRune(r)
		}
	}
	digits := b.String()
	if digits == "" {
		return 0
	}
	n, err := strconv.ParseInt(digits, 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func ReadPara() {
	if schedIdx < len(schedLines) {
		line := schedLines[schedIdx]
		schedIdx++
		if len(line) < 16 {
			line = line + strings.Repeat(" ", 16-len(line))
		} else if len(line) > 16 {
			line = line[:16]
		}
		curRec.ScAcct = line[0:4]
		curRec.ScPrin = parseImpliedDecimal(line[4:11], 2)
		curRec.ScRate = parseImpliedDecimal(line[11:15], 2)
		curRec.ScYears = parseIntField(line[15:16])
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	WsBal = storeDecimal(curRec.ScPrin, 8, 2)
	WsYear = storeInt(1, 2)
	for {
		if WsYear > curRec.ScYears {
			break
		}
		factor := decimal.NewFromInt(1).Add(curRec.ScRate.Shift(-2))
		product := WsBal.Mul(factor)
		rounded := roundHalfAway(product, 2)
		WsBal = storeDecimal(rounded, 8, 2)
		WsBalEd = formatWsBalEd(WsBal)
		line := curRec.ScAcct + " Y" + formatPIC99(WsYear) + " " + WsBalEd
		fmt.Fprint(os.Stdout, line+"\n")
		WsYear = storeInt(WsYear+1, 2)
	}
	WsBalEd = formatWsBalEd(WsBal)
	line2 := curRec.ScAcct + " FINAL " + WsBalEd
	fmt.Fprint(os.Stdout, line2+"\n")
	WsCount = storeInt(WsCount+1, 2)
	ReadPara()
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		if !os.IsNotExist(err) {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			schedLines = append(schedLines, scanner.Text())
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		f.Close()
	}
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	out := "SCHEDULES: " + formatPIC99(WsCount)
	fmt.Fprint(os.Stdout, out+"\n")
}

func main() {
	MainPara()
}
